-- 1000 Zeilen, ANALYZE, dann
-- 100 000 neue Zeilen 'Matura'
EXPLAIN ANALYZE SELECT * FROM anmeldung
WHERE kurs = 'Matura';
-- Seq Scan (cost=... rows=1)
--   (actual ... rows=100000)

ANALYZE anmeldung;
-- Seq Scan (cost=... rows=100014)
--   (actual ... rows=100000)

SELECT n_distinct, most_common_vals,
       most_common_freqs
FROM pg_stats
WHERE tablename = 'anmeldung'
  AND attname = 'status';
-- 2 | {bestaetigt,offen}
--   | {0.99023336,0.009766666}
